package main

import (
	"fmt"
	"strconv"
)

func main() {
	fmt.Println(string(rune(65))) // code point 65 -> "A"
	fmt.Println(strconv.Itoa(65)) // decimal text -> "65"
	// Output: A
	// 65
}

package main

import "fmt"

func main() {
	s := "hi"
	b := []byte(s) // allocates and copies
	b[0] = 'H'     // mutating the copy is safe
	fmt.Println(string(b)) // round-trip back to string
	fmt.Println(s)         // original unchanged
	// Output: Hi
	// hi
}

package main

import "fmt"

type Celsius float64
type Fahrenheit float64

func main() {
	c := Celsius(36.6)
	// arithmetic needs the underlying type, then convert back
	f := Fahrenheit(float64(c)*9/5 + 32)
	fmt.Printf("%.1f\n", float64(f))
	// Output: 97.9
}

