package solution

import "testing"

func TestCToF(t *testing.T) {
	cases := []struct {
		in   Celsius
		want Fahrenheit
	}{
		{0, 32},
		{100, 212},
		{-40, -40},
		{37, 98.6},
	}
	for _, c := range cases {
		if got := CToF(c.in); got != c.want {
			t.Errorf("CToF(%v)=%v want %v", c.in, got, c.want)
		}
	}
}

