func SumDigits(s string) (int, error) {
	n, err := strconv.Atoi(s) // text -> int, error if not numeric
	if err != nil {
		return 0, err
	}
	if n < 0 {
		n = -n // work with the magnitude
	}
	sum := 0
	for n > 0 {
		sum += n % 10 // last digit
		n /= 10       // drop it
	}
	return sum, nil
}

func NarrowToInt32(v int64) (int32, error) {
	if v < math.MinInt32 || v > math.MaxInt32 {
		return 0, fmt.Errorf("value %d out of int32 range", v)
	}
	return int32(v), nil // safe: value is known to fit
}
